/**
 * Standalone pubsub event-consumer worker entrypoint.
 * Selects the target block from argv[2] (the block's snake_case name) and starts that block's consumer.
 * The worker keeps its context until SIGTERM or SIGINT.
 * Given --liveness-port=<port>, it answers GET /live on that port with 200 and
 * every other request with 404, for a platform that starts a site only once it answers HTTP;
 * without the flag it opens no port.
 * Runs as: node dist/workers/event-consumer.js <block_snake_name> [--liveness-port=<port>]
 * Auto-generated by cruftfree-codegen-typescript. Do not edit manually.
 */
import { createServer, type Server } from 'node:http';
import { NestFactory } from '@nestjs/core';
import { type INestApplicationContext, Logger, Module, type Provider } from '@nestjs/common';
import { SettingsModule } from '../config/settings';
import { ViewingDbDatabaseModule } from '../viewing-db/database.module';
import { PubsubModule as MqPubsubModule } from '../mq/pubsub.module';
import { KafkaEventConsumer as MqConsumer } from '../mq/consumer';

const logger = new Logger('EventConsumer');

/** The flag a platform that starts a site only once it answers HTTP passes, with the port. */
const LIVENESS_PORT_FLAG = "--liveness-port";

/** The one route the liveness listener answers 200 on: the route the platform probes. */
const LIVENESS_PATH = "/live";

/** Milliseconds a client has to send its request; a slower one gets no answer. */
const LIVENESS_REQUEST_TIMEOUT_MS = 5_000;

/** Header lines read from a liveness request. */
const LIVENESS_MAX_HEADERS = 64;

/** Every interface: the platform's front end reaches the process over the container network. */
const LIVENESS_BIND_HOST = '0.0.0.0';

const HIGHEST_TCP_PORT = 65535;

/** The TCP port *value* names; any other value is refused. */
function tcpPort(value: string): number {
  const port = /^[0-9]+$/.test(value) ? Number(value) : Number.NaN;
  if (!Number.isInteger(port) || port < 1 || port > HIGHEST_TCP_PORT) {
    throw new Error(
      `${LIVENESS_PORT_FLAG} needs a TCP port (1-${HIGHEST_TCP_PORT}). Got: '${value}'. ` +
      `Pass it as ${LIVENESS_PORT_FLAG}=<port>.`,
    );
  }
  return port;
}

/**
 * The port the liveness flag names in *args* (the arguments after the block name), or undefined
 * when the platform passed none. Any other argument, a repeated flag, or a value that is not a
 * TCP port is refused: the worker never starts on a command it does not understand.
 */
function livenessPort(args: readonly string[]): number | undefined {
  const prefix = `${LIVENESS_PORT_FLAG}=`;
  let port: number | undefined;
  for (const arg of args) {
    if (!arg.startsWith(prefix)) {
      throw new Error(
        `event-consumer accepts only ${prefix}<port> after the block name. Got: '${arg}'.`,
      );
    }
    if (port !== undefined) {
      throw new Error(`event-consumer takes ${LIVENESS_PORT_FLAG} once. Got it again: '${arg}'.`);
    }
    port = tcpPort(arg.slice(prefix.length));
  }
  return port;
}

/**
 * Answer the platform's liveness probe on *port*: 200 for GET of the liveness path, 404 for every
 * other request. The answer says the process is up and checks no dependency. Resolves once the
 * listener is bound and rejects when it cannot bind; opens no port when *port* is undefined.
 */
function openLivenessEndpoint(port: number | undefined): Promise<Server | undefined> {
  if (port === undefined) {
    return Promise.resolve(undefined);
  }
  const server = createServer((req, res) => {
    const status = req.method === 'GET' && req.url === LIVENESS_PATH ? 200 : 404;
    res.writeHead(status, { 'Content-Length': '0', Connection: 'close' });
    res.end();
  });
  server.headersTimeout = LIVENESS_REQUEST_TIMEOUT_MS;
  server.requestTimeout = LIVENESS_REQUEST_TIMEOUT_MS;
  server.maxHeadersCount = LIVENESS_MAX_HEADERS;
  return new Promise((resolve, reject) => {
    server.once('error', reject);
    server.listen(port, LIVENESS_BIND_HOST, () => {
      server.off('error', reject);
      resolve(server);
    });
  });
}

/**
 * What every worker context holds. A standalone application context inherits nothing from
 * AppModule, so it imports the settings and every database module of the service itself, so
 * each MikroORM context a consumer resolves has its root, plus the root-module providers the
 * consumers reach through ModuleRef and what those inject.
 */
const WORKER_IMPORTS = [
  SettingsModule,
  ViewingDbDatabaseModule,
];

const WORKER_PROVIDERS: Provider[] = [
];

/** The 'mq' worker's context. */
@Module({
  imports: [...WORKER_IMPORTS, MqPubsubModule],
  providers: WORKER_PROVIDERS,
})
class MqWorkerModule {}

/** The longest delay a Node timer takes; the keep-alive timer only holds the process open. */
const KEEP_ALIVE_INTERVAL_MS = 2 ** 31 - 1;

/**
 * Keep a worker context running until SIGTERM or SIGINT, then stop its consumer and close it:
 * closing runs its providers' shutdown hooks, so an external queue's host stops its consumer
 * after the in-flight message settles. Returns once the signal handlers are installed.
 */
function closeOnShutdownSignal(
  app: INestApplicationContext,
  stopConsumer: () => Promise<void>,
): Promise<void> {
  const keepAlive = setInterval(() => undefined, KEEP_ALIVE_INTERVAL_MS);
  const shutdown = (signal: NodeJS.Signals): void => {
    process.off('SIGTERM', shutdown);
    process.off('SIGINT', shutdown);
    clearInterval(keepAlive);
    logger.log(`Event consumer stopping on ${signal}`);
    stopConsumer()
      .then(() => app.close())
      .then(
        () => {
          logger.log('Event consumer stopped');
          process.exit(0);
        },
        (err: unknown) => {
          logger.error('Event consumer failed to stop', err);
          process.exit(1);
        },
      );
  };
  process.on('SIGTERM', shutdown);
  process.on('SIGINT', shutdown);
  return Promise.resolve();
}

type BlockStarter = () => Promise<void>;

const BLOCK_STARTERS: Record<string, () => Promise<BlockStarter>> = {
  'mq': async () => {
    const app = await NestFactory.createApplicationContext(MqWorkerModule);
    const consumer = app.get(MqConsumer);
    return async () => {
      await consumer.start();
      await closeOnShutdownSignal(app, () => consumer.stop());
    };
  },
};

async function bootstrap(): Promise<void> {
  const blockName = process.argv[2];
  const starterFactory = blockName ? BLOCK_STARTERS[blockName] : undefined;
  if (!starterFactory) {
    const available = Object.keys(BLOCK_STARTERS).join(', ');
    throw new Error(
      `event-consumer requires a pubsub block's snake_case name as its first argument. ` +
      `Got: ${blockName ?? '(none)'}. Accepted block names: ${available}`,
    );
  }
  // The listener reports the process up, never a dependency: it opens before the block's
  // context boots and lives as long as the process.
  const liveness = await openLivenessEndpoint(livenessPort(process.argv.slice(3)));
  if (liveness) {
    logger.log(`Event consumer liveness listening path=${LIVENESS_PATH}`);
  }
  const start = await starterFactory();
  await start();
  logger.log(`Event consumer started for block '${blockName}'`);
}

bootstrap().catch((err) => {
  logger.error('Event consumer failed to start', err);
  process.exit(1);
});
